import { JsonInput } from '@drizztdourden08/tessera';
import { useState } from 'react';

const PlandoTexts = ({ value, save }: { value: Record<string, string>; save: (value: unknown) => void }) => {
  const [blocked, setBlocked] = useState(false);
  return (
    <>
      <JsonInput value={value} onChange={save} onProblem={(problem) => setBlocked(problem !== null)} shape="object" aria-label="Plando texts" />
      {blocked && <p>Not saved: fix the JSON first.</p>}
    </>
  );
};

import { NamedRange } from '@drizztdourden08/tessera';

const BALANCING = [{ label: 'Disabled', value: 0 }, { label: 'Normal', value: 50 }, { label: 'Extreme', value: 99 }];

const Balancing = ({ value, onChange }: { value: number; onChange: (value: number) => void }) => (
  <NamedRange value={value} onChange={onChange} names={BALANCING} min={0} max={99} aria-label="Progression balancing" />
);

import { Field, PathField } from '@drizztdourden08/tessera';

interface Bridge {
  pickFile: () => Promise<string | null>;
  showInFolder: (path: string) => void;
  pathOf: (file: File) => string;
}

const KeyFileField = ({ bridge, keyPath, setKeyPath }: { bridge: Bridge; keyPath: string | null; setKeyPath: (path: string | null) => void }) => (
  <Field label="Key file" hint="Only the path is stored.">
    <PathField
      value={keyPath}
      onChange={setKeyPath}
      onBrowse={bridge.pickFile}
      onReveal={bridge.showInFolder}
      resolvePath={bridge.pathOf}
      placeholder="No key file yet"
    />
  </Field>
);

