import { ManagedList } from '@drizztdourden08/tessera';

interface Server {
  id: string;
  name: string;
  host: string;
}

const ServerList = ({ servers, selectedId, onSelect, onAdd, onRename, onDelete, loading, error }: {
  servers: Server[];
  selectedId: string | null;
  onSelect: (id: string) => void;
  onAdd: () => void;
  onRename: (id: string, name: string) => void;
  onDelete: (id: string) => void;
  loading: boolean;
  error?: string;
}) => (
  <ManagedList
    title="Servers"
    items={servers}
    getId={(server) => server.id}
    getName={(server) => server.name}
    render={(server) => ({ meta: server.host })}
    selectedId={selectedId}
    onSelect={onSelect}
    onCreate={onAdd}
    createLabel="Add"
    onRename={onRename}
    onDelete={onDelete}
    loading={loading}
    error={error}
    empty="Add a server to host sessions on."
  />
);

import { MasterDetail } from '@drizztdourden08/tessera';
import { useState } from 'react';

interface Preset {
  id: string;
  name: string;
  options: Record<string, number>;
}

const PresetsScreen = ({ presets, save }: { presets: Preset[]; save: (preset: Preset) => Promise<void> }) => {
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [draft, setDraft] = useState<Preset | null>(null);
  const saved = presets.find((preset) => preset.id === selectedId);
  return (
    <MasterDetail
      list={{ title: 'Presets', items: presets, getId: (preset) => preset.id, getName: (preset) => preset.name }}
      selectedId={selectedId}
      onSelect={(id) => { setDraft(null); setSelectedId(id); }}
      detail={saved ? <pre>{JSON.stringify(draft ?? saved)}</pre> : null}
      dirty={draft !== null}
      onSave={async () => { if (draft) await save(draft); }}
      onDiscard={() => setDraft(null)}
      storageKey="presets.list-width"
    />
  );
};

